REPLACE INTO `item_combo_db` (`combo_id`,`script`) VALUES (3129,'.@sum = getequiprefinerycnt(EQI_HAND_R)+getequiprefinerycnt(EQI_HAND_L);
bonus bBaseAtk,15*(.@sum/3);
bonus bAtkRate,4*(.@sum/5);
if (BaseLevel >= 210) {
   bonus bPAtk,1;
   bonus bPow,2;
}
if (.@sum >= 14) {
   bonus2 bSkillCooldown,"KO_JYUMONJIKIRI",-2000;
   bonus2 bSkillAtk,"KO_JYUMONJIKIRI",35;
   if (.@sum >= 16) {
      .@a = getskilllv("OB_ZANGETSU");
      .@b = getskilllv("KG_KAGEHUMI");
      if (.@a > .@b)
         skill "OB_ZANGETSU",.@a;
      else
         skill "KG_KAGEHUMI",.@b;
      bonus2 bAddEle,Ele_All,15;
      if (.@sum >= 18) {
         bonus2 bSkillAtk,"KO_JYUMONJIKIRI",25;
         if (.@sum >= 20) {
            bonus2 bAddSize,Size_All,15;
         }
      }
   }
}
if (getequipid(EQI_HAND_R) == 510060)
   .@g = getenchantgrade(EQI_HAND_R);
else
   .@g = getenchantgrade(EQI_HAND_L);
if (.@g >= ENCHANTGRADE_D) {
   bonus bAtkRate,3;
   if (.@g >= ENCHANTGRADE_C) {
      bonus bLongAtkRate,15;
      bonus bPAtk,1;
      if (.@g >= ENCHANTGRADE_B) {
         bonus bPAtk,2;
         bonus bPow,3;
      }
   }
}
');
