REPLACE INTO `item_combo_db` (`combo_id`,`script`) VALUES (7419,'if (getequipid(EQI_HAND_L) == 510166) {
   .@sum = getequiprefinerycnt(EQI_HAND_R)+getequiprefinerycnt(EQI_HAND_L);
   bonus bAtkRate,.@sum;
   bonus bBaseAtk,25*.@sum;
   bonus2 bSkillAtk,"SHC_CROSS_SLASH",5*(.@sum/4);
   if (.@sum>=14) {
      bonus bCritAtkRate,20;
      if (.@sum>=17) {
         bonus bCRate,5;
         bonus bCritical,15;
         if (.@sum>=21) {
            bonus2 bSkillAtk,"SHC_CROSS_SLASH",15;
         }
      }
   }
}
');
